sp_widget.client_script:
api.controller = function($scope) {
  var c = this;

  $scope.$on("application.created", function(event, params) {
    c.loadPreview(params.app_id);
  });

  c.loadPreview = function(appId) {
    c.server.get({ action: "preview", app_id: appId }).then(function(r) {
      c.data.preview = r.data.preview;
      c.data.message = r.data.message;
    });
  };

  c.sendWelcome = function(appId) {
    c.server.get({ action: "send", app_id: appId }).then(function(r) {
      c.data.sent = r.data.sent;
      c.data.message = r.data.message;
    });
  };
};

sp_widget.css:
.ibar-notification-preview {
  padding: 20px;
}
.ibar-notification-preview .section-title {
  margin-bottom: 16px;
  font-size: 16px;
  font-weight: 600;
}
.ibar-notification-preview .email-preview {
  border: 1px solid #ddd;
  border-radius: 4px;
  overflow: hidden;
}
.ibar-notification-preview .preview-header {
  padding: 12px 16px;
  background: #f5f5f5;
  border-bottom: 1px solid #ddd;
  font-size: 13px;
}
.ibar-notification-preview .preview-body {
  padding: 16px;
}
.ibar-notification-preview .preview-actions {
  padding: 12px 16px;
  border-top: 1px solid #eee;
  background: #fafafa;
}

sp_widget.script:
(function() {
  data.preview = null;
  data.sent = false;
  data.message = "";

  try {
    if (input && input.action === "preview") {
      generatePreview(input.app_id);
      return;
    }
    if (input && input.action === "send") {
      sendWelcome(input.app_id);
      return;
    }
  } catch (e) {
    gs.error("IBAR Notification Preview error: " + e.message);
    data.message = "An error occurred.";
  }

  function generatePreview(appId) {
    var appGr = new GlideRecord("x_1433041_identi_0_application");
    if (!appGr.get(appId)) {
      data.message = "Application not found.";
      return;
    }

    var ownerName = "Not Assigned";
    var ownerEmail = "";
    if (appGr.getValue("assigned_owner")) {
      var userGr = new GlideRecord("sys_user");
      if (userGr.get(appGr.getValue("assigned_owner"))) {
        ownerName = userGr.getValue("name");
        ownerEmail = userGr.getValue("email");
      }
    }

    var portalLink = gs.getProperty("glide.servlet.uri") + "sp?id=appready-questionnaire&app_id=" + appId;

    data.preview = {
      recipient_name: ownerName,
      recipient_email: ownerEmail,
      subject: "Welcome - Application Onboarding Initiated",
      application_name: appGr.getValue("name"),
      portal_link: portalLink,
      due_date: appGr.getDisplayValue("due_date") || "Not Set"
    };
  }

  function sendWelcome(appId) {
    var appGr = new GlideRecord("x_1433041_identi_0_application");
    if (!appGr.get(appId)) {
      data.message = "Application not found.";
      return;
    }

    var ownerId = appGr.getValue("assigned_owner");
    if (!ownerId) {
      data.message = "No owner assigned. Cannot send welcome notification.";
      return;
    }

    var portalLink = gs.getProperty("glide.servlet.uri") + "sp?id=appready-questionnaire&app_id=" + appId;
    var subject = "Welcome - Application Onboarding Initiated";
    var message = "<p>Your application onboarding process has been initiated.</p>";
    message += "<p><strong>Application:</strong> " + appGr.getValue("name") + "</p>";
    message += "<p>Please complete the onboarding questionnaire:</p>";
    message += "<p><a href=\"" + portalLink + "\">Open Questionnaire</a></p>";
    message += "<p><strong>Due Date:</strong> " + (appGr.getDisplayValue("due_date") || "Not Set") + "</p>";

    var eventGr = new GlideRecord("x_1433041_identi_0_notification_event");
    eventGr.initialize();
    eventGr.setValue("application", appId);
    eventGr.setValue("event_type", "submission_confirmation");
    eventGr.setValue("recipient", ownerId);
    eventGr.setValue("subject", subject);
    eventGr.setValue("message", message);
    eventGr.setValue("sent_by", gs.getUserID());
    eventGr.setValue("sent_at", new GlideDateTime().getDisplayValue());
    eventGr.setValue("delivery_status", "sent");
    eventGr.insert();

    var threadGr = new GlideRecord("x_1433041_identi_0_communication_thread");
    threadGr.initialize();
    threadGr.setValue("application", appId);
    threadGr.setValue("thread_type", "general");
    threadGr.setValue("subject", subject);
    threadGr.setValue("created_by", gs.getUserID());
    threadGr.setValue("assigned_to", ownerId);
    threadGr.setValue("status", "open");
    threadGr.setValue("created_at", new GlideDateTime().getDisplayValue());
    threadGr.setValue("last_activity_at", new GlideDateTime().getDisplayValue());
    threadGr.insert();

    data.sent = true;
    data.message = "Welcome notification sent successfully.";
  }
})();
